def dehydrate_point(value):
    """
    Dehydrator for Point data.

    :param value: A Point-like object with numeric x and y coordinates.
    :type value: object
    :return: A serializable representation of the point (dictionary with 'x' and 'y' keys).
    """
    if value is None:
        return None
    # Try access via attributes
    try:
        x = float(value.x)
        y = float(value.y)
        return {"x": x, "y": y}
    except AttributeError:
        pass
    # Try access via coordinates attribute
    try:
        coords = value.coordinates
        # Some objects expose coordinates as a tuple or list
        x = float(coords[0])
        y = float(coords[1])
        return {"x": x, "y": y}
    except Exception:
        pass
    # Try treating as a sequence/tuple of two elements
    try:
        x = float(value[0])
        y = float(value[1])
        return {"x": x, "y": y}
    except Exception:
        pass
    raise TypeError("Cannot dehydrate the provided value: expected a Point-like object with numeric x and y coordinates.")

def keys(self):
    """
    Return the keys of the record.

    :return: list of key names
    """
    # Try to find a dictionary attribute that holds the record data
    if hasattr(self, "_data") and isinstance(self._data, dict):
        return list(self._data.keys())
    if hasattr(self, "data") and isinstance(self.data, dict):
        return list(self.data.keys())

    # If the instance itself behaves like a dictionary
    if isinstance(self, dict):
        return list(dict.keys(self))

    # Fallback to public attributes (exclude private/internal ones)
    return [k for k in self.__dict__ if not k.startswith("_")]

def index(self, key):
        """ Return the index of the given item.

        :param key: a key
        :return: index
        :rtype: int
        """
        # Attempt to use any underlying sequence that may be stored in the object.
        # Prefer a `data` or `values` attribute if present, falling back to
        # iterating over `self` itself.
        sequence = None
        if hasattr(self, "data"):
            sequence = self.data
        elif hasattr(self, "values"):
            sequence = self.values
        else:
            sequence = self

        for i, item in enumerate(sequence):
            if item == key:
                return i
        raise ValueError(f"{key} is not in list")

def data(self, *keys):
    """Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided that are not in the record will be inserted with a value
    of None; indexes provided that are out of bounds will trigger an
    IndexError."""
    # If no keys are given, return all fields.
    if not keys:
        return {field: value for field, value in zip(self._fields, self._values)}

    result = {}
    for key in keys:
        # Handle integer indices
        if isinstance(key, int):
            try:
                field = self._fields[key]
                value = self._values[key]
                result[field] = value
            except IndexError:
                raise IndexError(f"Index {key} out of bounds for record of length {len(self._fields)}")
        else:
            # Assume key is a field name
            if key in self._fields:
                idx = self._fields.index(key)
                result[key] = self._values[idx]
            else:
                result[key] = None
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # The dynamic subclass inherits from the existing Point class.
    # It stores the provided fields and SRID mapping as class attributes.
    return type(name, (Point,), {
        "fields": fields,
        "srid_map": srid_map,
    })

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        import warnings
        import functools
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(f"{func.__name__}: {message}", DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    parts = []
    for part in s.split('.'):
        try:
            parts.append(int(part))
        except ValueError:
            digits = ''
            for ch in part:
                if ch.isdigit():
                    digits += ch
                else:
                    break
            if digits:
                parts.append(int(digits))
    return tuple(parts)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if lock:
                lock.acquire()
            try:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
            finally:
                if lock:
                    lock.release()
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    def decorating_function(user_function):
        if maxsize <= 0:
            return user_function

        cache = {}
        usage = []
        hits = misses = 0

        def make_key(args, kwargs):
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                # include the type of each argument to separate same-value but different-type calls
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for v in kwargs.values())
            return key

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            try:
                key = make_key(args, kwargs)
            except (TypeError, AttributeError):
                # If arguments aren't hashable or can't be sorted, skip caching
                return user_function(*args, **kwargs)

            if key in cache:
                hits += 1
                # move key to end to mark as most recently used
                usage.remove(key)
                usage.append(key)
                return cache[key]
            misses += 1
            result = user_function(*args, **kwargs)

            if len(cache) >= maxsize:
                oldest = usage.pop(0)
                cache.pop(oldest, None)

            cache[key] = result
            usage.append(key)
            return result

        def cache_info():
            return {"hits": hits, "misses": misses, "maxsize": maxsize,
                    "currsize": len(cache)}

        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            usage.clear()
            hits = misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorating_function

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        first_key = next(iter(self))
    except StopIteration:
        raise KeyError('dictionary is empty')
    value = self.pop(first_key)
    return (first_key, value)

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            # Try to fetch from cache
            if lock is not None:
                # Acquire lock before checking the cache
                if hasattr(lock, "__enter__"):
                    with lock:
                        if k in cache:
                            return cache[k]
                else:
                    lock.acquire()
                    try:
                        if k in cache:
                            return cache[k]
                    finally:
                        lock.release()
            else:
                if k in cache:
                    return cache[k]
            # Compute value if not cached
            result = func(*args, **kwargs)
            # Store result in cache
            if lock is not None:
                if hasattr(lock, "__enter__"):
                    with lock:
                        cache[k] = result
                else:
                    lock.acquire()
                    try:
                        cache[k] = result
                    finally:
                        lock.release()
            else:
                cache[k] = result
            return result
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper
    return decorator

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    cls = type(self)
    attributes = []
    for name, value in cls.__dict__.items():
        if not name.startswith('_') and not callable(value):
            attributes.append(name)
    if all:
        for base in cls.__mro__[1:]:
            for name, value in base.__dict__.items():
                if (not name.startswith('_') and
                    not callable(value) and
                    name not in attributes):
                    attributes.append(name)
    return attributes

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value* or with
    *make_bins()* (depending on the initialization).
    """
    self.context = {}
    if hasattr(self, "initial_value") and self.initial_value is not None:
        n_bins = len(self.bins)
        self.bins = [self.initial_value] * n_bins
    else:
        self.bins = self.make_bins()

def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    lines = []
    if header is not None:
        lines.append(str(header))
    for point in self:
        # try to interpret point as (coords, value) pair
        coords = None
        value = None
        if isinstance(point, (list, tuple)):
            if len(point) == 2:
                coords, value = point[0], point[1]
            else:
                # fallback: first element may be a coordinate, rest a value
                coords = point[0]
                value = point[1:]
        else:
            # non-iterable point, treat it as a value
            value = point
            coords = None

        # convert coordinates
        if coords is None:
            coord_str = ""
        else:
            if isinstance(coords, (list, tuple)) and not isinstance(coords, (str, bytes)):
                coord_str = separator.join(map(str, coords))
            else:
                coord_str = str(coords)

        # convert value(s)
        if value is None:
            val_str = ""
        else:
            if isinstance(value, (list, tuple)) and not isinstance(value, (str, bytes)):
                val_str = separator.join(map(str, value))
            else:
                val_str = str(value)

        # build line
        if coord_str and val_str:
            line = coord_str + separator + val_str
        else:
            line = coord_str or val_str
        lines.append(line)
    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Identify the attribute that contains per-coordinate error information
    error_attrs = ("_err", "_errors", "errors")
    err_vec = None
    for attr in error_attrs:
        if hasattr(self, attr):
            obj = getattr(self, attr)
            if isinstance(obj, dict) and coord_name in obj:
                err_vec = obj[coord_name]
                break
    if err_vec is None:
        return []

    # Handle a single error value (not iterable)
    if not hasattr(err_vec, "__iter__") or isinstance(err_vec, (str, bytes)):
        # Treat any non‑zero numeric or non‑None value as an error at index 0
        if err_vec is None:
            return []
        try:
            # Skip NaN values
            if err_vec != err_vec:
                return []
        except Exception:
            pass
        return [0] if err_vec != 0 else []

    # For iterable error vectors, collect indices with finite, non‑zero errors
    indices = []
    for i, e in enumerate(err_vec):
        if e is None:
            continue
        try:
            # Treat NaN values as missing
            if e != e:
                continue
        except Exception:
            pass
        if e == 0:
            continue
        indices.append(i)
    return indices

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    return (
        hasattr(obj, "fill")
        and callable(getattr(obj, "fill"))
        and hasattr(obj, "request")
        and callable(getattr(obj, "request"))
    )

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        fill = getattr(obj, 'fill')
        compute = getattr(obj, 'compute')
    except AttributeError:
        return False
    return callable(fill) and callable(compute)

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    result = {}
    for key, value in d1.items():
        if key not in d2:
            result[key] = value
            continue
        v2 = d2[key]
        if isinstance(value, dict) and isinstance(v2, dict):
            # Recursive case
            if level == -1 or level > 1:
                new_level = level - 1 if level > 0 else -1
                subdiff = difference(value, v2, new_level)
                if subdiff:
                    result[key] = subdiff
            else:
                # For level 0 or 1, treat as a direct mismatch
                if value != v2:
                    result[key] = value
        else:
            if value != v2:
                result[key] = value
    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if len(coord) != len(self.edges):
        raise ValueError("Coordinate dimensionality does not match histogram")
    indices = []
    for dim, x in enumerate(coord):
        edges = self.edges[dim]
        if x < edges[0] or x >= edges[-1]:
            return
        idx = np.searchsorted(edges, x, side='right') - 1
        if idx < 0 or idx >= len(edges) - 1:
            return
        indices.append(idx)
    self.values[tuple(indices)] += weight

def _validate_labels(labels):
    import re

    errors = []

    key_regex = re.compile(r'^[A-Za-z0-9]([A-Za-z0-9._-]*[A-Za-z0-9])?$')
    value_regex = re.compile(r'^([A-Za-z0-9]([A-Za-z0-9._-]*[A-Za-z0-9])?)?$')

    def add_error(item, msg):
        errors.append({str(item): msg})

    for key, val in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            add_error(repr(key), 'expected string or bytes-like object')
            key_str = None
        else:
            key_str = key if isinstance(key, str) else key.decode()
            # Validate key pattern
            if '/' in key_str:
                prefix, _, name = key_str.rpartition('/')
                if not re.match(r'^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?$', prefix):
                    add_error(key_str, f"Label key '{key_str}' does not match the regex [...]")
                if not key_regex.match(name):
                    add_error(key_str, f"Label key '{key_str}' does not match the regex [...]")
            else:
                if not key_regex.match(key_str):
                    add_error(key_str, f"Label key '{key_str}' does not match the regex [...]")

        # Validate value type
        if isinstance(val, (list, tuple, set)):
            add_error(repr(val), 'expected string or bytes-like object')
        else:
            if not isinstance(val, (str, bytes)):
                add_error(repr(val), 'expected string or bytes-like object')
            else:
                val_str = val if isinstance(val, str) else val.decode()
                if not value_regex.match(val_str):
                    add_error(val_str, f"Label value '{val_str}' does not match the regex [...]")

    if errors:
        raise ValidationError(messages=errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a partial observer_schema dictionary from a Kubernetes manifest.
    All primitive values are replaced by None, except for identifying fields
    when `first_level` is True. The identifying fields are the top‑level
    ``apiVersion`` / ``kind`` and the ``metadata`` subfields ``name`` and
    ``namespace``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources.
        first_level (bool, optional): If True, indicates that the dictionary
            represents the whole observer_schema of a Kubernetes resource.

    Returns:
        dict: Generated partial observer_schema.
    """
    result = {}
    for key, value in manifest_dict.items():
        # Handle nested dictionaries
        if isinstance(value, dict):
            # Special handling for top‑level metadata when generating the
            # whole observer schema
            if first_level and key == "metadata":
                meta_out = {}
                for meta_key, meta_value in value.items():
                    # Preserve the identifying fields in metadata
                    if meta_key in ("name", "namespace"):
                        meta_out[meta_key] = meta_value
                    else:
                        meta_out[meta_key] = None
                result[key] = meta_out
            else:
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
            continue

        # Handle lists
        if isinstance(value, list):
            # For lists we replace each element:
            # - dict elements are processed recursively,
            # - other elements are replaced by None
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
            continue

        # Primitive values
        if first_level and key in ("apiVersion", "kind", "api_version"):
            result[key] = value
        else:
            result[key] = None

    return result

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Helper function that returns a very simple default observer schema
    # based on the resource's kind and name.  The actual default layout
    # may differ between projects; this is a placeholder that can be
    # replaced with a real implementation.
    def _default_observer_schema(resource):
        kind = getattr(resource, "kind", None)
        meta = getattr(resource, "metadata", {})
        name = getattr(meta, "name", None) if hasattr(meta, "name") else meta.get("name")
        return {
            "kind": kind,
            "name": name,
            "spec": {
                # Example: watch the status field for changes
                "onChange": {
                    "field": "status",
                },
            },
        }

    # Safety guard: ensure the application has the expected attributes.
    if not (hasattr(app, "spec") and hasattr(app.spec, "manifest")):
        return

    # Iterate over every resource in the application's manifest.
    for resource in getattr(app.spec.manifest, "resources", []):
        spec = getattr(resource, "spec", None)
        if spec is None:
            continue  # Skip resources that lack a spec section.

        # If the resource already has an observer schema, skip it.
        if hasattr(spec, "observer_schema") and spec.observer_schema is not None:
            continue

        # Otherwise set the default observer schema.
        default_schema = _default_observer_schema(resource)
        setattr(spec, "observer_schema", default_schema)

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os
    try:
        # Handle string filesystem path
        if isinstance(path, str):
            if not os.path.isdir(path):
                return False
            # Check for mandatory OCFL root marker file
            ocfl_root_file = os.path.join(path, ".ocfl-root")
            if not os.path.isfile(ocfl_root_file):
                return False
            # Check for objects directory
            objects_dir = os.path.join(path, "objects")
            if not os.path.isdir(objects_dir):
                return False
            return True
        else:
            # Assume a pyfilesystem (pyfs) root object
            # pyfs interfaces provide getinfo() and exists()
            if not hasattr(path, "getinfo") or not hasattr(path, "exists"):
                return False
            # Try to access the root marker file
            try:
                root_info = path.getinfo("/.ocfl-root")
                # pyfs getinfo raises FsError if not found
                if getattr(root_info, "is_dir", None):
                    return False
            except Exception:
                return False
            # Verify objects directory exists and is a directory
            try:
                objects_info = path.getinfo("/objects")
                if getattr(objects_info, "is_dir", None) is not True:
                    return False
            except Exception:
                return False
            return True
    except Exception:
        # Any unexpected error results in validation failure
        return False

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Ensure inventory is a mapping
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a mapping (dict).")

    # Extract spec_version from inventory if requested
    if extract_spec_version:
        type_val = inventory.get("type")
        if type_val is None:
            # No type key – rely on self.spec_version
            if not hasattr(self, "spec_version") or not self.spec_version:
                raise ValueError(
                    "Spec version not found in inventory and "
                    "self.spec_version is not set."
                )
        else:
            if not isinstance(type_val, str):
                raise ValueError("'type' key must be a string denoting spec version.")
            self.spec_version = type_val
    else:
        # Ensure self.spec_version is set
        if not hasattr(self, "spec_version") or not self.spec_version:
            raise ValueError("Spec version must be set on the instance.")

    # Validate spec_version against a list of supported versions
    supported_versions = {"1.0", "2.0", "3.0"}
    if self.spec_version not in supported_versions:
        raise ValueError(
            f"Unsupported spec version '{self.spec_version}'. "
            f"Supported versions are: {', '.join(sorted(supported_versions))}."
        )

    # Basic inventory structure checks
    required_keys = ["groups"]
    for key in required_keys:
        if key not in inventory:
            raise ValueError(f"Missing required key '{key}' in inventory.")

    groups = inventory["groups"]
    if not isinstance(groups, dict):
        raise ValueError("'groups' must be a mapping of group names to group data.")

    # Validate each group entry
    for group_name, group_data in groups.items():
        if not isinstance(group_name, str):
            raise ValueError(f"Group name '{group_name}' must be a string.")
        if not isinstance(group_data, dict):
            raise ValueError(f"Group '{group_name}' data must be a dictionary.")

    # If we reach here, validation passed
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Collect all digests that are required by the manifests
    required = set()
    # Accept both iterable of manifest dicts or dict of manifest dicts
    if isinstance(manifest_files, dict):
        iterable = manifest_files.values()
    else:
        iterable = manifest_files
    for mf in iterable:
        if isinstance(mf, dict):
            digests = mf.get('digests') or mf.get('hashes') or mf.get('signatures') or ()
        else:
            digests = mf
        if not digests:
            continue
        if isinstance(digests, (set, list, tuple)):
            required.update(digests)
        else:
            required.add(digests)
    # Ensure digests_used is an iterable
    digests_used_set = set(digests_used) if digests_used is not None else set()
    # Check that every required digest is used
    missing = required - digests_used_set
    if missing:
        raise ValueError(f"Missing digests required by manifest: {missing}")
    # Check for any unused digests that were not required
    unused = digests_used_set - required
    if unused:
        raise ValueError(f"Unneeded digests present in usage: {unused}")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure the input is of the same type
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an InventoryValidator instance")

    # Retrieve inventory data; we expect an ``inventory`` attribute that
    # contains a mapping of item identifiers to item data (usually a dict or
    # an object with ``version`` and ``timestamp`` attributes).
    try:
        current_items = self.inventory  # noqa: F821
        prior_items = prior.inventory   # noqa: F821
    except AttributeError:
        raise AttributeError("Both InventoryValidator instances must have an 'inventory' attribute")

    # Helper to safely extract known fields from different types of objects.
    def _get(item, *names):
        if isinstance(item, dict):
            for name in names:
                if name in item:
                    return item[name]
            return None
        # Fallback to attribute access; ``getattr`` returns ``None`` if not found
        for name in names:
            value = getattr(item, name, None)
            if value is not None:
                return value
        return None

    # 1. Every item present in the prior inventory must also exist in the
    #    current inventory.  This guarantees that the prior is not newer
    #    than the current one.
    missing_keys = set(prior_items) - set(current_items)
    if missing_keys:
        raise ValueError("Prior inventory contains items that are missing from the current inventory: %s" %
                         sorted(missing_keys))

    # 2. Version / timestamp validation for each item.
    for key, prior_item in prior_items.items():
        current_item = current_items[key]

        # Compare version numbers if they exist.  We treat a higher
        # version number in the prior as an error.
        prior_version = _get(prior_item, "version", "ver", "ver_num")
        current_version = _get(current_item, "version", "ver", "ver_num")
        if prior_version is not None and current_version is not None:
            try:
                if float(prior_version) > float(current_version):
                    raise ValueError(f"Item '{key}' in prior inventory has a newer version "
                                     f"({prior_version}) than the current inventory ({current_version})")
            except (TypeError, ValueError):
                # If the comparison fails (non numeric), skip the numeric check
                pass

        # Compare timestamps if they exist.  A timestamp in the prior that
        # is later than the corresponding timestamp in the current
        # inventory indicates an inconsistency.
        prior_ts = _get(prior_item, "timestamp", "time", "ts")
        current_ts = _get(current_item, "timestamp", "time", "ts")
        if prior_ts is not None and current_ts is not None:
            try:
                if prior_ts > current_ts:
                    raise ValueError(f"Item '{key}' in prior inventory has a later timestamp "
                                     f"({prior_ts}) than the current inventory ({current_ts})")
            except TypeError:
                # Non-comparable types: skip
                pass

    # 3. Compare overall inventory timestamps if available.
    inventory_ts_prior = _get(prior, "timestamp", "created_at", "created")
    inventory_ts_current = _get(self, "timestamp", "created_at", "created")
    if inventory_ts_prior is not None and inventory_ts_current is not None:
        try:
            if inventory_ts_prior >= inventory_ts_current:
                raise ValueError("Prior inventory timestamp is not older than the current inventory")
        except TypeError:
            # Non-comparable types: skip
            pass

    # If all checks pass, return True to indicate a valid prior.
    return True

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    from collections import defaultdict

    # helper to extract mapping from a state entry
    def _extract(state):
        mapping = defaultdict(set)
        if not isinstance(state, dict):
            return mapping
        lp = state.get("logical_paths") or state.get("paths")
        if not lp:
            return mapping

        # Accept dict of {logical_path: content_file} or list of dicts
        if isinstance(lp, dict):
            for logical_path, content in lp.items():
                if isinstance(content, list):
                    for c in content:
                        mapping[logical_path].add(c)
                else:
                    mapping[logical_path].add(content)
        elif isinstance(lp, list):
            for item in lp:
                if not isinstance(item, dict):
                    continue
                logical_path = item.get("logical_path")
                content = item.get("content_file") or item.get("content")
                if logical_path is None or content is None:
                    continue
                if isinstance(content, list):
                    for c in content:
                        mapping[logical_path].add(c)
                else:
                    mapping[logical_path].add(content)
        return mapping

    # Build a mapping of version number -> state dict
    version_states = {}
    if isinstance(inventory, dict):
        # Look for common structures
        if "states" in inventory and isinstance(inventory["states"], dict):
            for k, v in inventory["states"].items():
                try:
                    vk = int(k)
                except Exception:
                    continue
                version_states[vk] = v
        elif "versions" in inventory and isinstance(inventory["versions"], list):
            for v in inventory["versions"]:
                if not isinstance(v, dict):
                    continue
                vid = v.get("id") or v.get("version")
                try:
                    vid = int(vid)
                except Exception:
                    continue
                version_states[vid] = v
        else:
            # Assume the inventory itself is a state for the requested version
            try:
                version_states[version] = inventory
            except Exception:
                pass

    result = defaultdict(set)
    # Include entries from the requested version and all subsequent versions
    for vnum in sorted([k for k in version_states if k >= version]):
        state = version_states[vnum]
        state_map = _extract(state)
        for path, files in state_map.items():
            result[path].update(files)

    return dict(result)

def validate_fixity(self, fixity, manifest_files):
    """
    Validate the fixity block in an inventory.

    Parameters
    ----------
    fixity : dict
        The fixity section of the inventory.
    manifest_files : set or list
        The set of file paths that are present in the manifest.

    Raises
    ------
    ValueError
        If the fixity block is malformed or references a file
        that is not present in the manifest.
    """
    if not isinstance(fixity, dict):
        raise ValueError("The fixity block must be a dictionary")

    # The fixity block may contain a 'file' mapping or list of file entries
    file_block = fixity.get("file")
    if file_block is None:
        # Some inventories may not include a file-based fixity block; nothing to validate
        return

    # Convert manifest_files to a set for efficient lookups
    manifest_set = set(manifest_files)

    # Support `file` as either a dict (path -> hash) or a list of file entry dicts
    if isinstance(file_block, dict):
        for path in file_block:
            if not isinstance(path, str):
                raise ValueError(f"File path '{path}' in fixity block is not a string")
            if path not in manifest_set:
                raise ValueError(f"File '{path}' referenced in fixity block not found in manifest")
    elif isinstance(file_block, list):
        for idx, entry in enumerate(file_block):
            if not isinstance(entry, dict):
                raise ValueError(f"Entry {idx} in fixity file block is not a dictionary")
            # Most common structure: { "path": "...", ... }
            path = entry.get("path")
            if not isinstance(path, str):
                raise ValueError(f"Entry {idx} missing or has non-string 'path' key")
            if path not in manifest_set:
                raise ValueError(f"File '{path}' referenced in fixity block not found in manifest")
    else:
        raise ValueError("The 'file' key in fixity block must be a dict or a list")
    # If all checks pass, simply return None (no error)

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    data = {}
    try:
        entries = os.listdir(folder)
    except Exception:
        return data

    # Collect files
    for entry in entries:
        full_path = os.path.join(folder, entry)
        if not os.path.isfile(full_path):
            continue
        base, ext = os.path.splitext(entry)
        if base not in data:
            data[base] = {'xml': None, 'files': []}
        if ext.lower() == ".xml":
            data[base]['xml'] = full_path
        else:
            data[base]['files'].append(full_path)

    # Only keep groups that have an XML file
    result = {base: info for base, info in data.items() if info['xml'] is not None}
    return result

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    return content.replace('w:st="', 'w-st="')

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _pretty(obj, level):
        indent_str = '  ' * level
        if isinstance(obj, dict):
            if not obj:
                return "{}"
            items = []
            for k in sorted(obj):
                v = obj[k]
                items.append(f"{k!r}: {_pretty(v, level+1)}")
            inner = f",\n{indent_str}  ".join(items)
            return f"{{\n{indent_str}  {inner}\n{indent_str}}}"
        elif isinstance(obj, (list, tuple, set)):
            if not obj:
                return "[]"
            open_sym = '[' if isinstance(obj, list) else '(' if isinstance(obj, tuple) else '{'
            close_sym = ']' if isinstance(obj, list) else ')' if isinstance(obj, tuple) else '}'
            items = [f"{_pretty(v, level+1)}" for v in obj]
            inner = f",\n{indent_str}  ".join(items)
            return f"{open_sym}\n{indent_str}  {inner}\n{indent_str}{close_sym}"
        elif hasattr(obj, "__dict__"):
            cls_name = type(obj).__name__
            # filter out private/protected attributes
            attrs = {k: v for k, v in obj.__dict__.items() if not k.startswith("_")}
            attr_str = _pretty(attrs, level+1)
            if debug:
                return f"{cls_name}(\n{indent_str}  {attr_str}\n{indent_str})  <id {id(obj)}>"
            else:
                return f"{cls_name}(\n{indent_str}  {attr_str}\n{indent_str})"
        else:
            return repr(obj)

    return _pretty(self, indent)

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.

    """
    config = {
        "auth": {
            "user": user
        },
        "etcd": {
            "host": etcd_host,
            "port": etcd_port
        }
    }
    return config

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys

    def wrapper(*args, **kwargs):
        name = namefunc(*args, **kwargs)
        if sys.version_info[0] < 3:
            # In Python 2, 'unicode' type is available
            try:
                # If the name is a unicode object, encode it to utf-8
                if isinstance(name, unicode):  # type: ignore
                    return name.encode('utf-8')
            except NameError:
                # 'unicode' name does not exist in Python 3 (but we are in <3 branch)
                pass
        # For Python 3 or if name is already bytes/str, return as is
        return name

    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Python 3.8+ has importlib.metadata built-in
        import importlib.metadata as importlib_metadata
    except ImportError:
        # fallback for older Python versions
        try:
            import importlib_metadata
        except ImportError:
            return "0.0.0"

    # Use the package name if available, otherwise derive from module name
    pkg_name = __package__ if __package__ else __name__.split(".")[0]

    try:
        return importlib_metadata.version(pkg_name)
    except Exception:
        return "0.0.0"

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Define commonly used separators for known styles
    separators = {
        "dot": ".",
        "dash": "-",
        "underscore": "_",
        "space": " ",
        "comma": ", ",
        "slash": "/",
        "none": "",
        "plain": " ",
        "text": " ",
    }
    # The style can be supplied directly as the separator
    if style in separators:
        sep = separators[style]
    else:
        # Allow custom separators specified as 'sep=...'
        if isinstance(style, str) and style.startswith("sep="):
            sep = style[4:]
        else:
            # Default to concatenation without separator
            sep = ""
    # Convert each piece to string and join
    return sep.join(str(p) for p in pieces)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    for piece in pieces:
        if '+' in piece:
            return '.'
    return '+'

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return version
    # Preserve leading 'v' or other non-numeric prefix if present
    prefix = ''
    rest = version
    if rest and not rest[0].isdigit():
        prefix = rest[0]
        rest = rest[1:]
    parts = rest.split('.')
    if not parts:
        return version
    # Find the last numeric part to increment
    for i in range(len(parts) - 1, -1, -1):
        if parts[i].isdigit():
            last_idx = i
            break
    else:
        # No numeric part found
        return version
    original_last = parts[last_idx]
    width = len(original_last)
    try:
        new_num = int(original_last) + 1
    except ValueError:
        return version
    new_last = str(new_num).zfill(width)
    # If increment increases length, keep the new length
    if len(new_last) < width:
        new_last = new_last.rjust(width, '0')
    parts[last_idx] = new_last
    return prefix + '.'.join(parts)

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper to detect a MappingNode by inspecting its tag.
    def _is_mapping(node):
        return hasattr(node, 'tag') and isinstance(node.tag, str) and node.tag.endswith('map')

    # Recursively merge two mapping node values (both have `value` attribute that is a list of tuples).
    def _merge_mapping_nodes(node_a, node_b):
        # Build index for node_a's key-value pairs
        index_a = {k.value: i for i, (k, _) in enumerate(node_a.value)}
        for key_node, val_node in node_b.value:
            key = key_node.value
            if key in index_a:
                i = index_a[key]
                _, existing_val = node_a.value[i]
                if _is_mapping(existing_val) and _is_mapping(val_node):
                    # Both are mappings → recurse
                    _merge_mapping_nodes(existing_val, val_node)
                else:
                    # Non‑mapping or different types → override with last value
                    node_a.value[i] = (key_node, val_node)
            else:
                # New key – append
                node_a.value.append((key_node, val_node))
                index_a[key] = len(node_a.value) - 1

    # Building the merged list
    merged = []
    key_index = {}   # maps key value to index in `merged` list
    for key_node, value_node in nodes:
        key = key_node.value
        if key in key_index:
            i = key_index[key]
            _, existing_val = merged[i]
            if _is_mapping(existing_val) and _is_mapping(value_node):
                _merge_mapping_nodes(existing_val, value_node)
            else:
                # Override with last value; keep the original key node
                merged[i] = (key_node, value_node)
        else:
            merged.append((key_node, value_node))
            key_index[key] = len(merged) - 1

    return merged

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # argparse stores actions in the `_actions` attribute.  Each action holds the `option_strings`
    # that were provided when the argument was added.  Merge all of them and return as a
    # single string, preserving the original order.
    if not hasattr(parser, "_actions"):
        return ""
    flags = []
    for action in parser._actions:
        if hasattr(action, "option_strings") and action.option_strings:
            flags.extend(action.option_strings)
    return " ".join(flags)

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper to determine if a node is a mapping node (i.e., has a list of pairs as its value)
    def is_mapping_node(node):
        # A mapping node normally has a tag ending with ':map' and a list value
        try:
            return isinstance(node.value, list)
        except AttributeError:
            return False

    # Merge two lists of key/value pairs recursively.
    def merge_lists(list1, list2):
        merged_dict = {}
        merged_order = []

        # Helper to add a pair to merged_dict ensuring order on first appearance
        def add_pair(k_node, v_node):
            key = k_node.value if hasattr(k_node, 'value') else None
            if key not in merged_dict:
                merged_dict[key] = v_node
                merged_order.append((k_node, v_node))
            else:
                # Handle conflict
                existing_v = merged_dict[key]
                if is_mapping_node(existing_v) and is_mapping_node(v_node):
                    # Recursive merge
                    merged_v = merge_nodes(existing_v, v_node)
                    merged_dict[key] = merged_v
                    # Replace in order list as well
                    for idx, (kn, vn) in enumerate(merged_order):
                        if kn.value == key:
                            merged_order[idx] = (kn, merged_v)
                            break
                else:
                    # Last wins
                    merged_dict[key] = v_node
                    for idx, (kn, vn) in enumerate(merged_order):
                        if kn.value == key:
                            merged_order[idx] = (kn, v_node)
                            break

        # Add items from both lists
        for k_node, v_node in list1:
            add_pair(k_node, v_node)
        for k_node, v_node in list2:
            add_pair(k_node, v_node)

        return merged_order

    # Merge two mapping nodes
    def merge_nodes(node1, node2):
        if not (is_mapping_node(node1) and is_mapping_node(node2)):
            return node2  # If either is not a mapping node, last wins
        # Create a new node with merged value list
        merged_value = merge_lists(node1.value, node2.value)
        # Preserve tag and construct a new mapping node
        try:
            new_node = node1.__class__(tag=node1.tag, value=merged_value)
        except Exception:
            # Fallback if the constructor differs
            new_node = node1
            new_node.value = merged_value
        return new_node

    result = []
    seen_keys = {}

    for key_node, value_node in nodes:
        key = key_node.value if hasattr(key_node, 'value') else None
        if key in seen_keys:
            # Merge with existing
            existing_key_node, existing_value_node = seen_keys[key]
            merged_value = merge_nodes(existing_value_node, value_node)
            # Update the record in result list (keep the original key node)
            seen_keys[key] = (existing_key_node, merged_value)
            for idx, (k, v) in enumerate(result):
                if k.value == key:
                    result[idx] = (k, merged_value)
                    break
        else:
            seen_keys[key] = (key_node, value_node)
            result.append((key_node, value_node))

    return result

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        if action.option_strings:
            flags.extend(action.option_strings)
    return ' '.join(flags)

def parse_arguments(*unparsed_arguments):
    import argparse
    parser = argparse.ArgumentParser()
    # Add any global arguments here if needed, e.g.:
    # parser.add_argument('--verbose', action='store_true')
    namespace, _ = parser.parse_known_args(unparsed_arguments)
    return {'global': namespace}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    from collections import Counter

    parsed = {}
    remaining_lists = []

    # If there are no subparsers, return all arguments as remaining
    if not subparsers:
        return {}, list(unparsed_arguments)

    for name, parser in subparsers.items():
        # parse_known_args will return a Namespace and a list of unparsed arguments that this parser could not handle
        ns, rem = parser.parse_known_args(list(unparsed_arguments))
        parsed[name] = ns
        remaining_lists.append(rem)

    # Compute intersection of remaining arguments across all subparsers
    if remaining_lists:
        occ = Counter(remaining_lists[0])
        for rest in remaining_lists[1:]:
            occ &= Counter(rest)
    else:
        occ = Counter()

    # Preserve original order for the returned remaining arguments
    remaining = []
    for token in unparsed_arguments:
        if occ.get(token, 0) > 0:
            remaining.append(token)
            occ[token] -= 1

    return parsed, remaining

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args.

    Supports placeholders in the format `{key}`, `:key` and `${key}`.
    If a key is not present in ``url_args`` its placeholder is left unchanged.
    """
    import re

    # Separate query string to avoid replacing placeholders inside it unintentionally.
    path, sep, query = url.partition('?')

    def _repl(match):
        key = match.group('key')
        return str(url_args.get(key, match.group(0)))

    # Patterns for different placeholder styles.
    patterns = [
        r'{(?P<key>[^{}]+)}',          # {key}
        r':(?P<key>[^/:\?]+)',         # :key
        r'\${(?P<key>[^}]+)}',         # ${key}
    ]

    for pat in patterns:
        path = re.sub(pat, _repl, path)

    return path + sep + query if sep else path

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        flags.extend(action.option_strings)
    return ' '.join(flags)

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    def _recurse(obj):
        # Recursively traverse and replace keys
        if isinstance(obj, dict):
            new_obj = {}
            for key, val in obj.items():
                new_key = register_number if key == register_value else key
                new_obj[new_key] = _recurse(val)
            return new_obj

        if isinstance(obj, list):
            return [_recurse(item) for item in obj]

        if isinstance(obj, tuple):
            return tuple(_recurse(item) for item in obj)

        return obj

    return _recurse(flow_params)

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    result = set()
    for sub in cls.__subclasses__():
        result.add(sub)
        result.update(subclasses(sub))
    return list(result)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string:
        return 0
    base = len(alphabet)
    # Build a mapping from character to its numeric value
    value_map = {ch: idx for idx, ch in enumerate(alphabet)}
    result = 0
    for ch in string:
        if ch not in value_map:
            raise ValueError(f"Character '{ch}' not found in alphabet")
        result = result * base + value_map[ch]
    return result

def unquote(name):
    """Remove leading and trailing quotes from the given name."""
    if not isinstance(name, str):
        return name
    while len(name) >= 2 and name[0] == name[-1] and name[0] in ("'", '"'):
        name = name[1:-1]
    return name

import os, shlex, re

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 0 if os.name == 'nt' else 1

    # POSIX: delegate to shlex.split which handles escape sequences and quotes
    if platform == 1:
        return shlex.split(s, posix=True)

    # Windows: split on whitespace; everything quoted together; backslashes not processed specially
    # Regex: match either quoted substrings (including spaces) or sequences of non-whitespace
    token_re = re.compile(r'''(".*?"|\S+)''', re.DOTALL)
    tokens = []
    for m in token_re.finditer(s):
        token = m.group(0)
        if token.startswith('"') and token.endswith('"'):
            token = token[1:-1]
        tokens.append(token)
    return tokens

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '-i', '--exclude-standard'],
            stderr=subprocess.DEVNULL,
            text=True
        )
    except subprocess.CalledProcessError:
        output = ''
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip == '127.0.0.1' or ip.startswith('127.'):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0].split('%')[0]  # strip zone index if present
                if ip == '::1':
                    return True
        if isinstance(host, str) and host.lower() == 'localhost':
            return True
    except socket.gaierror:
        pass
    return False

def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    THis is useful to run a single ssh command and pass a one line script.

    :param script:
    :return:
    """
    if script is None:
        return ""
    # Handle string input
    if isinstance(script, (list, tuple)):
        lines = [str(line).strip() for line in script if str(line).strip() != ""]
    else:
        lines = [line.strip() for line in str(script).splitlines() if line.strip() != ""]
    return seperator.join(lines)

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Interpret matcher
    name = None
    default = None

    if isinstance(matcher, (tuple, list)):
        if len(matcher) == 0:
            raise ValueError("Matcher tuple/list must contain at least the variable name.")
        name = str(matcher[0])
        if len(matcher) > 1:
            default = matcher[1]
    elif isinstance(matcher, dict):
        if 'name' not in matcher:
            raise ValueError("Matcher dict must contain a 'name' key.")
        name = str(matcher['name'])
        default = matcher.get('default')
    elif isinstance(matcher, str):
        # support 'VAR' or 'VAR:default'
        if ':' in matcher:
            parts = matcher.split(':', 1)
            name = parts[0]
            default = parts[1] if parts[1] != '' else None
        else:
            name = matcher
    else:
        raise TypeError("Matcher must be a tuple, list, dict, or string.")

    # Get the value from environment
    value = os.getenv(name)

    if value is None:
        if default is None:
            raise EnvironmentError(f"Environment variable '{name}' not found and no default provided.")
        value = default

    return value

def remove_ending_os_sep(input_list):
    if not isinstance(input_list, list):
        raise TypeError("input_list must be a list")
    processed = []
    for item in input_list:
        if not isinstance(item, str):
            raise TypeError("All items in input_list must be strings")
        if len(item) > 1 and item.endswith(os.sep):
            processed.append(item[:-1])
        else:
            processed.append(item)
    return processed

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if strip:
        pattern = pattern.strip()
    return re.escape(pattern)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    # Build the command list
    if isinstance(commands, str):
        commands = [commands]
    elif isinstance(commands, (list, tuple)):
        commands = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")
    if isinstance(args, str):
        args = [args]
    elif isinstance(args, (list, tuple)):
        args = list(args)
    else:
        raise TypeError("args must be a string or a list/tuple of strings")
    cmd = commands + args

    if verbose:
        print("Running command:", " ".join(cmd))

    # Handle stderr
    stderr_pipe = subprocess.PIPE if not hide_stderr else subprocess.DEVNULL

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_pipe,
            text=True,
        )
        if verbose:
            if result.stdout:
                print(result.stdout)
            if not hide_stderr and result.stderr:
                print(result.stderr)
        return result.returncode
    except Exception as e:
        if verbose:
            print("Error running command:", e)
        return -1

