@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        # If the caller passed a single string treat it as a list of one item.
        if isinstance(values, str):
            values = [values]
        bookmarks = []
        for val in values:
            if not isinstance(val, str):
                raise TypeError(
                    f"Raw value must be a string, got {type(val).__name__}"
                )
            try:
                bookmark = Bookmark.from_raw_value(val)
            except Exception as exc:
                raise ValueError(
                    f"Failed to parse bookmark from raw value '{val}': {exc}"
                ) from exc
            bookmarks.append(bookmark)
        return cls(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*,
    if that is of a sequence type).
    """
    seq_type = type(seq)

    # If seq is a built‑in sequence type, return it directly
    if isinstance(seq, (list, tuple, set, str, bytes, bytearray)):
        return seq, seq_type

    # If seq is file‑like, read in chunks
    if hasattr(seq, "read"):
        size = bufsize or 8192
        parts = []
        while True:
            chunk = seq.read(size)
            if not chunk:
                break
            parts.append(chunk)
        if not parts:
            data = seq_type()
        else:
            first = parts[0]
            # concatenate bytes/bytearray separately from str/other
            if isinstance(first, (bytes, bytearray)):
                data = b"".join(parts)
            else:
                data = "".join(parts)
        return data, seq_type

    # General iterable: convert to list
    try:
        return list(seq), seq_type
    except Exception:
        # Fallback: return as-is
        return seq, seq_type

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    try:
        from zope.interface import Invalid
    except Exception:
        # If zope.interface is not available, we cannot perform verification.
        raise RuntimeError("zope.interface module is required for verifyObject")

    errors = []

    # Check interface provision unless tentative
    if not tentative:
        try:
            provided = iface.providedBy(candidate)
        except Exception:
            provided = False
        if not provided:
            errors.append(
                f"Candidate {candidate!r} does not provide interface {iface!r}"
            )

    # Helper: compare signatures of callable objects
    def _sig_matches(iface_obj, cand_obj):
        try:
            import inspect

            iface_sig = inspect.signature(iface_obj)
            cand_sig = inspect.signature(cand_obj)
        except Exception:
            # If we cannot obtain signatures, we assume they match
            return True

        # Compare parameter kinds and names, ignoring defaults and varargs
        def _params(lst):
            return [
                p
                for p in lst
                if p.kind in (
                    p.POSITIONAL_ONLY,
                    p.POSITIONAL_OR_KEYWORD,
                    p.KEYWORD_ONLY,
                )
            ]

        iface_params = _params(list(iface_sig.parameters.values()))
        cand_params = _params(list(cand_sig.parameters.values()))
        return (
            len(iface_params) == len(cand_params)
            and [
                p.name for p in iface_params
            ]
            == [p.name for p in cand_params]
        )

    # Extract interface members (methods and attributes)
    for name in dir(iface):
        if name.startswith("_"):
            continue
        try:
            iface_obj = getattr(iface, name)
        except Exception:
            continue

        if callable(iface_obj):
            # Method
            if not hasattr(candidate, name):
                errors.append(f"Method {name} missing in candidate {candidate!r}")
                continue
            cand_obj = getattr(candidate, name)
            if not callable(cand_obj):
                errors.append(
                    f"Attribute {name} in candidate {candidate!r} is not callable"
                )
                continue
            if not _sig_matches(iface_obj, cand_obj):
                errors.append(
                    f"Method {name} of candidate {candidate!r} does not match "
                    f"the signature of interface {iface!r}"
                )
        else:
            # Attribute
            if not hasattr(candidate, name):
                errors.append(
                    f"Attribute {name} missing in candidate {candidate!r}"
                )

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.
    Returns True if candidate can satisfy the interface,
    else False. When *tentative* is True only structural
    checks are performed.
    """
    # Determine the class to test
    cand_cls = candidate if isinstance(candidate, type) else type(candidate)

    # 1. Quick subclass check
    try:
        if issubclass(cand_cls, iface):
            return True
    except Exception:
        pass

    # 2. Collect required attribute names from iface
    names = None

    # If iface is an abstract base class, use its abstract method set
    if isinstance(iface, type) and hasattr(iface, "__abstractmethods__"):
        names = iface.__abstractmethods__

    # If iface has a __dict__, we treat it as a class-like object
    elif hasattr(iface, "__dict__"):
        names = [
            name for name in iface.__dict__
            if not (name.startswith("_") and name.endswith("_"))
        ]

    # Otherwise, try to interpret iface as an iterable of attribute names
    else:
        try:
            names = [name for name in iface if isinstance(name, str)]
        except Exception:
            names = None

    # If we couldn't determine any required names, use tentative flag
    if not names:
        return tentative

    # Ensure candidate has all required attributes
    for name in names:
        if not hasattr(cand_cls, name):
            return False

    return True

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if default is __marker:
        # No default provided – let the underlying dict raise
        return super().pop(key)
    # Default provided – use the underlying dict's pop with default
    return super().pop(key, default)

