def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Diaspora request.

    The heuristics are:
    1. Check for a header that signals a Diaspora request.
    2. Check the JSON body for keys that are typical of a public or private Diaspora
       message (`public` or `private`).
    3. Check for legacy payload markers (e.g., a `payload` dict containing
       common fields like `id`, `name`, or `type`).

    Parameters
    ----------
    request : RequestType
        The incoming request object.

    Returns
    -------
    bool
        True if the request appears to be a Diaspora request, False otherwise.
    """
    # 1. Header based detection (the header might be used by some integrations)
    header_val = None
    try:
        header_val = request.headers.get("X-Diaspora-Request") if hasattr(request, "headers") else None
    except Exception:
        header_val = None
    if header_val in {"1", "true", "yes", "True"}:
        return True

    # 2. Body based detection
    body = {}
    try:
        # Many frameworks expose a .json() method that returns a dict
        body = request.json() if hasattr(request, "json") else {}
    except Exception:
        body = {}
    # If no JSON method, try parsing if the request has a 'body' attribute
    if not body and hasattr(request, "body"):
        try:
            import json
            body = json.loads(request.body) if isinstance(request.body, (str, bytes)) else request.body
        except Exception:
            body = {}

    # Check for explicit public/private flags
    if body.get("public") is True or body.get("private") is True:
        return True

    # 3. Legacy payload detection
    payload = body.get("payload")
    if isinstance(payload, dict):
        # Typical legacy fields
        legacy_keys = {"id", "name", "type", "action"}
        if legacy_keys & payload.keys():
            return True

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Try to get the request path (many frameworks expose it as `path` or `url`)
    try:
        path = getattr(request, 'path', None) or getattr(request, 'url', None) or ''
    except Exception:
        path = ''
    if isinstance(path, str) and path.startswith('/_matrix'):
        return True

    # Inspect headers for common Matrix markers
    headers = getattr(request, 'headers', {})
    if not isinstance(headers, dict):
        headers = {}

    # Matrix APIs typically send JSON payloads
    content_type = headers.get('content-type', headers.get('Content-Type', ''))
    if 'application/json' in content_type.lower():
        return True

    # Matrix uses "Bearer" tokens in the Authorization header
    auth = headers.get('authorization', headers.get('Authorization', ''))
    if auth.lower().startswith('bearer'):
        return True

    return False

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote URL to determine the content type."""
    try:
        import requests
        response = requests.head(url, allow_redirects=True, timeout=5)
        if response.status_code == 200:
            return response.headers.get("Content-Type")
    except Exception:
        pass
    return None

