def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json, xml.etree.ElementTree as ET

    # Try to parse JSON first
    try:
        data = json.loads(document)
        # Normalize keys (some implementations use camelCase or underscored names)
        # Ensure aliases and links are lists
        if 'aliases' in data and not isinstance(data['aliases'], list):
            data['aliases'] = [data['aliases']]
        if 'links' in data and not isinstance(data['links'], list):
            data['links'] = [data['links']]
        return data
    except json.JSONDecodeError:
        pass

    # Fallback to XRD (XML) parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        raise ValueError("Document is not valid JSON or XRD XML")

    # Helper to strip namespace
    def _local_name(tag: str) -> str:
        return tag.split('}', 1)[-1] if '}' in tag else tag

    result = {}
    # Keep track of list keys
    list_keys = set()

    for child in root:
        tag = _local_name(child.tag)
        if tag == 'Subject':
            result['subject'] = child.text.strip() if child.text else ''
        elif tag == 'Alias':
            result.setdefault('aliases', []).append(child.text.strip() if child.text else '')
        elif tag == 'Link':
            link_info = {}
            for attr, value in child.attrib.items():
                link_info[attr] = value
            result.setdefault('links', []).append(link_info)
        else:
            text = child.text.strip() if child.text else None
            if tag in result:
                # convert to list if not already
                if not isinstance(result[tag], list):
                    result[tag] = [result[tag]]
                result[tag].append(text)
            else:
                result[tag] = text

    # Ensure expected keys exist
    result.setdefault('aliases', [])
    result.setdefault('links', [])

    return result

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Parse the handle into local part and host
    try:
        _, host = handle.split('@', 1)
    except ValueError:
        # Invalid handle format
        return {}

    # Construct the webfinger URL
    url = f"https://{host}/.well-known/webfinger?resource=acct:{handle}"

    # Prepare the request with appropriate Accept header
    try:
        import urllib.request
        import urllib.error
        req = urllib.request.Request(
            url,
            headers={'Accept': 'application/xrd+xml, application/json'}
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            content_type = resp.headers.get('Content-Type', '').lower()
            data = resp.read()
    except Exception:
        # Network error or other issue
        return {}

    # Try to parse as JSON first
    try:
        import json
        json_obj = json.loads(data.decode('utf-8'))
        # Expect "links" key
        result = {}
        if isinstance(json_obj, dict):
            links = json_obj.get('links', [])
            if isinstance(links, list):
                for link in links:
                    rel = link.get('rel')
                    href = link.get('href')
                    if rel and href:
                        result.setdefault(rel, []).append(href)
        return result
    except Exception:
        pass  # Not JSON

    # Try to parse as XML (XRD)
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(data)
        ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}  # typical XRD namespace

        def find_links():
            # XRD can have Link elements directly or within Subject
            for link in root.findall('.//xrd:Link', ns):
                rel = link.get('rel')
                href = link.get('href')
                if rel and href:
                    yield rel, href

        result = {}
        for rel, href in find_links():
            result.setdefault(rel, []).append(href)
        return result
    except Exception:
        pass  # Not XML

    # Fallback if content type indicates plain text or unknown format
    if 'text/plain' in content_type or 'text/html' in content_type:
        try:
            text = data.decode('utf-8')
            # Very basic key:value parsing
            result = {}
            for line in text.splitlines():
                if ':' in line:
                    key, val = line.split(':', 1)
                    result[key.strip()] = val.strip()
            return result
        except Exception:
            pass

    # If all parsing attempts fail, return empty dict
    return {}

def list_of_file_names(settings_dirs, spec_option):
    """Return a list of file names found in the specified directories,
    optionally filtered by a glob-style pattern passed in spec_option.
    """
    import os
    import fnmatch

    # Ensure the directories input is a list
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs)

    result = []

    for dir_path in dirs:
        if not os.path.isdir(dir_path):
            # Skip if the directory does not exist
            continue

        try:
            entries = os.listdir(dir_path)
        except OSError:
            # If listing fails (e.g., permission error), skip this directory
            continue

        for name in entries:
            full_path = os.path.join(dir_path, name)
            if not os.path.isfile(full_path):
                # We are only interested in regular files
                continue

            if spec_option is None:
                # No pattern, accept all files
                result.append(full_path)
            else:
                # If the pattern is a string and matches the fnmatch style,
                # use fnmatch; otherwise, try to use it as a regular expression.
                if isinstance(spec_option, str):
                    # First, attempt glob matching
                    try:
                        if fnmatch.fnmatch(name, spec_option):
                            result.append(full_path)
                            continue
                    except Exception:
                        pass

                    # Fallback: try to interpret as a regular expression
                    try:
                        import re
                        if re.search(spec_option, name):
                            result.append(full_path)
                    except Exception:
                        # If regex compilation fails, ignore this pattern
                        pass

    return result

