@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise IRValidatorException("yaml_file argument is required")
    try:
        with open(yaml_file, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
    except Exception as exc:
        raise IRValidatorException(f"Failed to load YAML file '{yaml_file}': {exc}")
    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(
            f"Missing mandatory fields in YAML file '{yaml_file}': {', '.join(missing)}"
        )
    return data

def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.
    """
    defaults = {}
    spec_params = getattr(self, 'spec', {}).get('parameters', [])
    for param in spec_params:
        name = param.get('name')
        if not name:
            continue
        default = param.get('default')
        if default is None:
            cfg = getattr(self, 'config', None)
            if cfg and name in cfg:
                default = cfg[name]
            else:
                os_mod = globals().get('os')
                if os_mod:
                    env_val = os_mod.environ.get(name.upper())
                    if env_val is not None:
                        default = env_val
        if default is not None:
            defaults[name] = default
    return defaults

