def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Find the command definition
    cmd_def = None
    if hasattr(self, 'commands'):
        try:
            cmd_def = self.commands[command_name]
        except (KeyError, TypeError):
            return None
    elif hasattr(self, 'command_defs'):
        try:
            cmd_def = self.command_defs[command_name]
        except (KeyError, TypeError):
            return None
    else:
        return None

    # Get the options dictionary (dict or object with 'options')
    options = None
    if isinstance(cmd_def, dict):
        options = cmd_def.get('options')
    else:
        options = getattr(cmd_def, 'options', None)

    if not isinstance(options, dict):
        return None

    # Return the option specification if it exists
    return options.get(argument_name)

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    required = getattr(self, "required", None) or getattr(self, "requires", None) or getattr(self, "required_args", None)
    if not required:
        return True
    # Ensure required is iterable
    required_keys = list(required)
    if args is None:
        args = {}
    missing = [k for k in required_keys if k not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for item in args:
        # Support two or three element sequences
        if isinstance(item, (list, tuple)):
            if len(item) == 3:
                name, value, max_len = item
            elif len(item) == 2:
                name, value = item
                max_len = None
            else:
                continue
        else:
            continue

        if max_len is not None:
            if hasattr(value, "__len__") and len(value) > max_len:
                raise ValueError(
                    f"Argument '{name}': length {len(value)} exceeds maximum {max_len}"
                )

def validate_choices_args(self, args):
