def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    min_args = getattr(self, "min_args", None)
    max_args = getattr(self, "max_args", None)
    length = len(args)
    if min_args is not None and length < min_args:
        raise ValueError(
            f"Too few arguments: expected at least {min_args}, got {length}"
        )
    if max_args is not None and length > max_args:
        raise ValueError(
            f"Too many arguments: expected at most {max_args}, got {length}"
        )
    return True

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.
    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Accept both dicts and iterable of (key, value) tuples
    control_args = {}
    nested_args = {}

    try:
        items = args.items()
    except AttributeError:
        items = args

    for key, value in items:
        # Ensure key is a string for prefix checks
        if not isinstance(key, str):
            # If key is not a string, skip categorization
            continue

        # Detect control arguments (prefix with "control_" or "control.")
        if key.startswith("control_") or key.startswith("control."):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if extra_vars is None:
            return vars_dict
        # If a single dict is passed, merge it directly
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict
        for ev in extra_vars:
            if ev is None:
                continue
            # Handle plain strings like "key=value"
            if isinstance(ev, str):
                if '=' in ev:
                    key, val = ev.split('=', 1)
                    vars_dict[key.strip()] = val.strip()
                else:
                    # Treat string without '=' as a flag key with boolean True
                    vars_dict[ev.strip()] = True
            # Handle tuples or lists that represent key/value pairs
            elif isinstance(ev, (list, tuple)) and len(ev) == 2:
                key, val = ev
                vars_dict[str(key)] = val
            # Merge if it's a dictionary
            elif isinstance(ev, dict):
                vars_dict.update(ev)
        return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.
    By default all the values are strings.
    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Define type mapping for specific parsers.  Extend this dictionary
    # with parser names and the arguments that need explicit conversion.
    # Example mapping:
    # {
    #     'main': {'port': int, 'debug': bool, 'timeout': float, 'tags': list},
    #     'virsh': {'timeout': int, 'dry-run': bool},
    #     'ospd': {'username': str, 'password': str},
    # }
    type_mapping = {
        # Example mappings; populate as needed
        'main': {
            'port': int,
            'debug': bool,
            'timeout': float,
            'tags': list,
        },
        'virsh': {
            'timeout': int,
            'dry-run': bool,
        },
        'ospd': {
            'username': str,
            'password': str,
        },
    }

    # Helpers for converting common types
    def _to_bool(val):
        if isinstance(val, bool):
            return val
        try:
            return val.lower() in ('1', 'true', 'yes', 'on')
        except AttributeError:
            return bool(val)

    def _to_int(val):
        try:
            return int(val)
        except (TypeError, ValueError):
            return val

    def _to_float(val):
        try:
            return float(val)
        except (TypeError, ValueError):
            return val

    def _to_list(val):
        if isinstance(val, list):
            return val
        if isinstance(val, str):
            return [item.strip() for item in val.split(',') if item.strip()]
        return [val]

    # Acquire the conversion map for the current parser
    conversions = type_mapping.get(parser_name, {})

    # Iterate over all keys in values_dict and cast if needed
    for key, raw_val in values_dict.items():
        target_type = conversions.get(key)
        if target_type is None:
            continue

        # Perform casting based on the target type
        if target_type is bool:
            cast_val = _to_bool(raw_val)
        elif target_type is int:
            cast_val = _to_int(raw_val)
        elif target_type is float:
            cast_val = _to_float(raw_val)
        elif target_type is list:
            cast_val = _to_list(raw_val)
        elif target_type is str:
            cast_val = str(raw_val)
        else:
            # If there's a custom type (e.g., datetime), attempt direct cast
            try:
                cast_val = target_type(raw_val)
            except Exception:
                # Fallback: keep as raw string
                cast_val = raw_val

        values_dict[key] = cast_val
    # No return needed; values_dict is modified in place.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os, json

    # Possible spec file names in order of preference
    candidate_files = (
        'plugin.json',
        'plugin.yml',
        'plugin.yaml',
        'spec.json',
        'spec.yml',
        'spec.yaml',
    )

    spec_path = None
    for fname in candidate_files:
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_path = path
            break

    if not spec_path:
        # No spec file found
        return {}

    # Load the spec file (JSON or YAML)
    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            _, ext = os.path.splitext(spec_path)
            if ext.lower() == '.json':
                spec_data = json.load(f)
            else:
                try:
                    import yaml
                except ImportError:
                    # Attempt to fall back to JSON parsing
                    try:
                        spec_data = json.load(f)
                    except Exception:
                        return {}
                else:
                    spec_data = yaml.safe_load(f)
    except Exception:
        return {}

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    if isinstance(spec_data, dict):
        return _flatten(spec_data)
    # If spec data is not a dict (unlikely), return empty dict
    return {}
